"use client";

import { LucideMoon } from "lucide-react";
import { motion, AnimatePresence } from "motion/react";
import { useSyncExternalStore } from "react";

import type { ReactFC } from "@/lib/types";
import { cn } from "@/lib/utils";

const noop = () => {
  // The hydration snapshot has no external subscription to release.
};
const subscribe = () => noop;
export interface ThemeSwitchSliderProps {
  theme: string;
  setTheme: (theme: string) => void;
  isDark: boolean;
  toggleTheme: () => void;
  className?: string | undefined;
}
export const ThemeSwitchSlider: ReactFC<ThemeSwitchSliderProps> = ({
  isDark,
  toggleTheme,
  className,
}) => {
  const mounted = useSyncExternalStore(
    subscribe,
    () => true,
    () => false
  );
  if (!mounted) {
    return <div className={cn("h-[34px] w-[60px]", className)} />;
  }
  return (
    <motion.button
      type="button"
      aria-label={isDark ? "Switch to light theme" : "Switch to dark theme"}
      onClick={toggleTheme}
      className={cn(
        "relative h-[34px] w-[60px] cursor-pointer rounded-2xl p-1 transition-colors duration-200",
        "hover:scale-105 active:scale-100",
        isDark
          ? "bg-violet-900/80 hover:bg-violet-900"
          : "bg-sky-400/40 hover:bg-sky-400/60",
        className
      )}
      whileHover={{
        scale: 1.05,
      }}
      whileTap={{
        scale: 0.98,
      }}
    >
      {/* Stars */}
      <div className="relative bottom-[12px] left-0">
        {[
          {
            x: 10,
            y: 3,
          },
          {
            x: 3,
            y: 7,
          },
          {
            x: 12,
            y: 18,
          },
          {
            x: 15,
            y: 10,
          },
          {
            x: 19,
            y: 4,
          },
          {
            x: 22,
            y: 14,
          },
        ].map((position, i) => {
          const size = i % 2 === 0 ? 2 : 1;
          return (
            <motion.div
              key={i}
              className={cn(
                "absolute rounded-full bg-white/90",
                size === 2 ? "h-[2px] w-[2px]" : "h-[1px] w-[1px]"
              )}
              style={{
                left: position.x,
                top: position.y,
              }}
              initial={{
                opacity: 0,
                y: 10,
              }}
              animate={{
                opacity: isDark ? 1 : 0,
                scale: isDark ? [1, 1.2, 1] : 1,
                y: isDark ? 0 : 10,
              }}
              transition={{
                delay: i * 0.05,
                duration: 0.2,
                scale: {
                  delay: i * 0.3,
                  duration: 2,
                  repeat: Infinity,
                },
              }}
            />
          );
        })}
      </div>

      {/* Sun/Moon Circle */}
      <motion.div
        className={cn(
          "absolute top-0 bottom-0 my-auto h-7 w-7 rounded-full",
          "flex items-center justify-center",
          "transition-colors duration-200",
          isDark
            ? "border-2 border-white/90 bg-white/40"
            : "border-2 border-amber-400/70 bg-amber-200"
        )}
        animate={{
          x: isDark ? 24 : 0,
        }}
        transition={{
          damping: 25,
          stiffness: 300,
          type: "spring",
        }}
      >
        <AnimatePresence mode="wait">
          {isDark && (
            <motion.div
              key="moon"
              initial={{
                scale: 0,
              }}
              animate={{
                scale: 1,
              }}
              exit={{
                scale: 0,
              }}
            >
              <LucideMoon className="h-4 w-4 text-white" />
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </motion.button>
  );
};

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
  value: string;
  label?: string | undefined;
  emoji?: string | undefined;
  icon?: LucideIcon | undefined;
  closeOnClick?: boolean | undefined;
  disabled?: boolean | undefined;
}
